import{_ as t,o as a,c as r,ag as d}from"./chunks/framework.TQKaXlFR.js";const u=JSON.parse('{"title":"文档首页","description":"","frontmatter":{"layout":"home","title":"文档首页","hero":{"name":"星辉后台","text":"使用与开发指南","tagline":"快速上手、功能操作、组件扩展与部署维护。","actions":[{"theme":"brand","text":"开始使用","link":"/guide/quickstart"},{"theme":"alt","text":"查看功能边界","link":"/overview/capabilities"}]},"features":[{"title":"使用已有能力","details":"用户、角色、字典、通知、文件、AI配置、表单与资讯，按身份和授权操作。","link":"/features/accounts"},{"title":"从源码扩展","details":"对照页面、接口、服务、迁移与测试，理解现有组件的参数和失败状态。","link":"/development/module-extension"},{"title":"自己部署与维护","details":"分开管理应用、API和静态文档，明确配置、备份、升级及质量门禁。","link":"/operations/deployment"}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),o={name:"index.md"};function i(s,e,l,n,h,c){return a(),r("div",null,[...e[0]||(e[0]=[d('<h2 id="先选一个阅读入口" tabindex="-1">先选一个阅读入口 <a class="header-anchor" href="#先选一个阅读入口" aria-label="Permalink to &quot;先选一个阅读入口&quot;">​</a></h2><p>这份文档面向管理人员、业务使用者、开发者和部署维护者。阅读公开文档不需要登录；操作管理应用仍需要有效登录、操作权限和符合接口要求的身份。</p><table tabindex="0"><thead><tr><th>你的目标</th><th>从这里开始</th><th>正常结果</th></tr></thead><tbody><tr><td>首次运行项目</td><td><a href="./guide/quickstart.html">快速开始</a> → <a href="./guide/verification.html">运行验证</a></td><td>连接自己配置的数据库、缓存和 API，完成登录与最小验证</td></tr><tr><td>使用管理页面</td><td><a href="./features/accounts.html">功能手册</a> → <a href="./features/menus.html">三个菜单组</a></td><td>能找到当前身份实际获权的入口，不把菜单显示当成服务端授权</td></tr><tr><td>新增功能</td><td><a href="./development/structure.html">项目结构</a> → <a href="./development/module-extension.html">新增模块</a></td><td>知道应修改哪层代码、怎样增加迁移和验证权限</td></tr><tr><td>复用页面组件</td><td><a href="./components/overview.html">组件概览</a></td><td>找到本项目实际适配与组件契约，而不是照搬上游示例</td></tr><tr><td>上线或升级</td><td><a href="./operations/deployment.html">部署</a> → <a href="./operations/backup-restore.html">备份恢复</a> → <a href="./releases/upgrade.html">升级</a></td><td>形成可回滚、可核验的部署组合</td></tr><tr><td>确认交付状态</td><td><a href="./releases/versions.html">候选版本</a> → <a href="./operations/quality-gates.html">质量门禁</a></td><td>区分代码实现、本地验证、供应商联调与正式 CI</td></tr></tbody></table><h2 id="怎样检索" tabindex="-1">怎样检索 <a class="header-anchor" href="#怎样检索" aria-label="Permalink to &quot;怎样检索&quot;">​</a></h2><p>点击顶部“搜索文档”，或按 <code>Ctrl+K</code>（macOS 使用 <code>⌘K</code>），输入功能名称，例如“字典管理”；部署配置可搜索 <code>CONFIG_MASTER_KEY</code>。结果来自随站点发布的本地全文索引，无需外部搜索服务。选择结果进入章节，右侧“本页目录”可直接跳转到具体规则。按 <code>Esc</code> 关闭搜索。</p><p>如果没有结果，换用页面实际名称或配置键，去相应分类侧栏查找。静态站点离线缓存未更新时，应刷新页面并确认应用与文档的候选版本匹配；不要为了查文档删除登录存储。</p><h2 id="文档与运行状态" tabindex="-1">文档与运行状态 <a class="header-anchor" href="#文档与运行状态" aria-label="Permalink to &quot;文档与运行状态&quot;">​</a></h2><p>本次 Pages 发布目标为<a href="https://beidaomitu233.github.io/xinghui-admin-vue3/" target="_blank" rel="noreferrer">后台静态演示</a>和<a href="https://beidaomitu233.github.io/xinghui-admin-vue3/docs/" target="_blank" rel="noreferrer">文档中心</a>，实际部署状态以<a href="https://github.com/beidaomitu233/xinghui-admin-vue3/actions" target="_blank" rel="noreferrer">公开仓库 Actions</a>及 HTTP 验收为准。静态演示使用浏览器本地示例数据，不连接真实后端或供应商；这次发布不等同后端正式发行或完整应用质量 CI。</p><p>当前是开发候选文档，不是正式发行或企业采用证明。页面存在不代表所有供应商已接通；微信网站真实扫码、短信发送、远端 CI 与独立机器验证的限制见<a href="./overview/capabilities.html">能力边界</a>。本机站点可访问也不等于已公开互联网发布。</p><p>文档只有一个正文来源：前端仓库 <code>apps/docs/content/</code>。默认静态基路径为 <code>/docs/</code>，子目录托管可通过 <code>DOCS_BASE</code> 设置完整路径；章节使用 <code>.html</code> 地址。默认“文档中心、当前页面帮助、版本说明”入口不携带用户信息或 API 凭据。部署失败时按<a href="./operations/troubleshooting.html">故障排查</a>检查静态目录和反向代理，不把文档 404 当成登录失效。</p><h2 id="核对来源" tabindex="-1">核对来源 <a class="header-anchor" href="#核对来源" aria-label="Permalink to &quot;核对来源&quot;">​</a></h2><ul><li>站点包及命令：前端 <code>apps/docs/package.json</code>。</li><li>分类和章节合同：前端 <code>apps/docs/.vitepress/chapters.mjs</code>。</li><li>搜索、基路径和导航：前端 <code>apps/docs/.vitepress/config.mts</code>、<code>search.mjs</code>。</li><li>应用入口：前端 <code>apps/web-ele/src/layouts/basic.vue</code>。</li><li>本站构建机制参考 <a href="https://vuejs.github.io/vitepress/v1/guide/getting-started" target="_blank" rel="noreferrer">VitePress 1.x 文档</a>，本地全文搜索参考<a href="https://vuejs.github.io/vitepress/v1/reference/default-theme-search" target="_blank" rel="noreferrer">官方搜索说明</a>。</li></ul>',12)])])}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
